-- Add unique index on normalized email + companyId
-- Using a generated column for the normalized email
ALTER TABLE users 
ADD COLUMN email_normalized VARCHAR(320) GENERATED ALWAYS AS (LOWER(TRIM(email))) STORED;

ALTER TABLE users 
ADD UNIQUE INDEX idx_users_normalized_email_company (companyId, email_normalized);

